private function isInsideParentheses(Tokens $tokens, int $index): bool
{
    $depth = 0;
    for ($i = $index - 1; $i >= 0; --$i) {
        $token = $tokens[$i];

        if ($token->equals(')')) {
            ++$depth;
        } elseif ($token->equals('(')) {
            if (0 === $depth) {
                return true;
            }

            --$depth;
        } elseif ($token->equalsAny(['{', '}', ';', [T_OPEN_TAG]])) {
            return false;
        }
    }

    return false;
}

private function isPropertyDeclaration(Tokens $tokens, int $index): bool
{
    $index = $tokens->getNextMeaningfulToken($index);

    while (null !== $index) {
        $token = $tokens[$index];

        if ($token->isGivenKind(T_VARIABLE)) {
            return true;
        }

        if (
            $token->isGivenKind([T_FUNCTION, T_CONST, T_CLASS, T_INTERFACE, T_TRAIT])
            || (\defined('T_ENUM') && $token->isGivenKind(T_ENUM))
            || $token->equalsAny(['(', ')', '{', '}', ';', ',', '='])
        ) {
            return false;
        }

        $index = $tokens->getNextMeaningfulToken($index);
    }

    return false;
}

